        tags: Option<Vec<String>>,
        #[arg(
            long = "no-tag",
            help = "Only return entries without any tags (mutex with -t)"
        )]
        no_tag: bool,
        #[arg(
            long,
            help = "Start date (default: 1 year ago). Accepts today, yesterday, this_week, last_week, or YYYY-MM-DD"
