use crate::api::client::ApiClient;
use crate::models::{ResultWithDefaultError, TimeEntry};
use crate::utilities;
use std::collections::HashMap;

const BILLING_INCREMENT_SECONDS: i64 = 15 * 60;
const MINIMUM_BILLING_SECONDS: i64 = 30 * 60;

pub struct InvoiceCommand;

fn billable_duration_seconds(duration: i64) -> i64 {
    let rounded = ((duration + BILLING_INCREMENT_SECONDS - 1) / BILLING_INCREMENT_SECONDS)
        * BILLING_INCREMENT_SECONDS;
    rounded.max(MINIMUM_BILLING_SECONDS)
}

fn invoice_totals(entries: &[TimeEntry]) -> Vec<(String, i64)> {
    let mut totals = HashMap::<String, i64>::new();
    for entry in entries.iter().filter(|entry| entry.billable && !entry.is_running()) {
        let project = entry
            .project
            .as_ref()
            .map(|project| project.name.clone())
            .unwrap_or_else(|| "No Project".to_string());
        *totals.entry(project).or_default() += billable_duration_seconds(entry.duration);
    }

    let mut totals: Vec<_> = totals.into_iter().collect();
    totals.sort_by(|(name_a, seconds_a), (name_b, seconds_b)| {
        seconds_b.cmp(seconds_a).then_with(|| name_a.cmp(name_b))
    });
    totals
}

impl InvoiceCommand {
    pub async fn execute(
        api_client: impl ApiClient,
        since: Option<String>,
        until: Option<String>,
    ) -> ResultWithDefaultError<()> {
        let (since, until) = utilities::normalize_time_entry_list_filters(since, until)?;
        let entries = api_client.get_time_entries_filtered(since, until).await?;
        let totals = invoice_totals(&entries);

        if totals.is_empty() {
            println!("(no data)");
            return Ok(());
        }

        let total: i64 = totals.iter().map(|(_, seconds)| seconds).sum();
        for (project, seconds) in totals {
            println!("{seconds}s  {project}");
        }
        println!("{total}s  Total");
        Ok(())
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use chrono::{TimeZone, Utc};

    fn entry(duration: i64, billable: bool, project: Option<&str>) -> TimeEntry {
        TimeEntry {
            id: duration,
            description: String::new(),
            start: Utc.timestamp_opt(0, 0).unwrap(),
            stop: Some(Utc.timestamp_opt(duration.max(0), 0).unwrap()),
            duration,
            billable,
            workspace_id: 1,
            tags: vec![],
            project: project.map(|name| crate::models::Project {
                id: 1,
                name: name.to_string(),
                workspace_id: 1,
                client: None,
                is_private: false,
                active: true,
                at: Utc.timestamp_opt(0, 0).unwrap(),
                created_at: Utc.timestamp_opt(0, 0).unwrap(),
                color: String::new(),
                billable: Some(true),
            }),
            task: None,
            created_with: None,
        }
    }

    #[test]
    fn rounds_each_entry_then_applies_thirty_minute_floor() {
        let totals = invoice_totals(&[
            entry(1, true, Some("Work")),
            entry(901, true, Some("Work")),
            entry(1800, true, Some("Work")),
        ]);
        assert_eq!(totals, vec![("Work".to_string(), 4500)]);
    }

    #[test]
    fn filters_non_billable_and_running_entries_and_sorts_totals() {
        let mut running = entry(-1, true, Some("Ignored"));
        running.stop = None;
        let totals = invoice_totals(&[
            entry(1800, true, Some("Zulu")),
            entry(1800, true, Some("Alpha")),
            entry(1800, false, Some("Ignored")),
            running,
            entry(1800, true, None),
        ]);
        assert_eq!(
            totals,
            vec![
                ("Alpha".to_string(), 1800),
                ("No Project".to_string(), 1800),
                ("Zulu".to_string(), 1800),
            ]
        );
    }

    #[test]
    fn empty_invoice_has_no_totals() {
        assert!(invoice_totals(&[entry(60, false, Some("Ignored"))]).is_empty());
    }
